      sse_encode_box_autoadd_conflict_view(self, serializer);
    }
  }

  @protected
  void sse_encode_opt_box_autoadd_u_32(int? self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs

    sse_encode_bool(self != null, serializer);
    if (self != null) {
      sse_encode_box_autoadd_u_32(self, serializer);
    }
  }

  @protected
  void sse_encode_pairing_event(PairingEvent self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    switch (self) {
      case PairingEvent_Invite(uri: final uri):
        sse_encode_i_32(0, serializer);
        sse_encode_String(uri, serializer);
      case PairingEvent_Confirm(
        peerName: final peerName,
        shortId: final shortId,
        code: final code,
      ):
        sse_encode_i_32(1, serializer);
        sse_encode_String(peerName, serializer);
        sse_encode_String(shortId, serializer);
        sse_encode_String(code, serializer);
      case PairingEvent_Paired(name: final name):
        sse_encode_i_32(2, serializer);
        sse_encode_String(name, serializer);
      case PairingEvent_Failed(reason: final reason):
        sse_encode_i_32(3, serializer);
        sse_encode_String(reason, serializer);
    }
  }

  @protected
  void sse_encode_send_update(SendUpdate self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    switch (self) {
      case SendUpdate_Progress(
        sent: final sent,
        toSend: final toSend,
        paths: final paths,
      ):
        sse_encode_i_32(0, serializer);
        sse_encode_u_64(sent, serializer);
        sse_encode_u_64(toSend, serializer);
        sse_encode_u_32(paths, serializer);
      case SendUpdate_Retrying(reason: final reason):
        sse_encode_i_32(1, serializer);
        sse_encode_String(reason, serializer);
      case SendUpdate_Done(
        files: final files,
        bytes: final bytes,
        millis: final millis,
        paths: final paths,
      ):
        sse_encode_i_32(2, serializer);
        sse_encode_u_32(files, serializer);
        sse_encode_u_64(bytes, serializer);
        sse_encode_u_64(millis, serializer);
        sse_encode_u_32(paths, serializer);
      case SendUpdate_Failed(reason: final reason):
        sse_encode_i_32(3, serializer);
        sse_encode_String(reason, serializer);
    }
  }

  @protected
  void sse_encode_u_32(int self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    serializer.buffer.putUint32(self);
  }

  @protected
  void sse_encode_u_64(BigInt self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    serializer.buffer.putBigUint64(self);
  }

  @protected
  void sse_encode_u_8(int self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    serializer.buffer.putUint8(self);
  }

  @protected
  void sse_encode_unit(void self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
  }

  @protected
  void sse_encode_usize(BigInt self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    serializer.buffer.putBigUint64(self);
  }
}

